"""巡检组件的响应和结果合同；不定义流程控制。"""
import json
from collections import Counter
from datetime import datetime, timezone

from hep_lfx import current_run, invoke


def now():
    return datetime.now(timezone.utc).isoformat()


def snapshot():
    return current_run.get()["shared"]


async def request(connection, operation, args):
    value = await invoke(current_run.get()["config"]["connections"][connection], operation, args)
    if not isinstance(value, dict) or value.get("isError"):
        raise ValueError("上游 MCP 工具执行失败")
    if value.get("structuredContent") is not None:
        value = value["structuredContent"]
    elif isinstance(value.get("content", value.get("contents")), list):
        value = json.loads("\n".join(item["text"] for item in value.get("content", value.get("contents")) if isinstance(item.get("text"), str)))
    if not isinstance(value, dict) or value.get("code", 0) not in (0, 200):
        raise ValueError("上游业务请求失败")
    return value


def rows(reply):
    data = reply.get("data")
    value = reply.get("rows", data.get("rows", data.get("records", data.get("list"))) if isinstance(data, dict) else data)
    if not isinstance(value, list):
        raise ValueError("上游响应缺少列表，不能作为空结果")
    return value


def scope(value):
    shared = snapshot()
    if value.get("scope") != shared["scope"]["requested"]:
        raise ValueError("输入与冻结范围不一致")
    return {**value, "items": shared["assets"]}


def item(asset, result):
    return {"assetId": asset["assetId"], "ip": asset.get("ip"), "hostname": asset.get("hostname"), "observed_at": now(), **result}


def summary(kind, value):
    items = value["items"]
    counts = Counter(item["status"] for item in items)
    return {"kind": kind, "scope": snapshot()["scope"], "status": "incomplete" if counts["failed"] or counts["unknown"] else "completed",
            "counts": {status: counts[status] for status in ("normal", "abnormal", "unknown", "not_applicable", "failed")}, "items": items}


def aggregate(kind, checks):
    return {"kind": kind, "scope": snapshot()["scope"], "status": "completed" if all(check.get("status") == "completed" for check in checks.values()) else "incomplete", "checks": checks}

