"""状态证据判断；流程及批次定义见本包 flow.json。"""
from datetime import datetime
from ipaddress import ip_address
from hep_lfx import business


def timestamp(value):
    try:
        return isinstance(value, str) and len(value) >= 19 and bool(datetime.fromisoformat(value.replace("Z", "+00:00")))
    except ValueError:
        return False


def check(value):
    asset = value["item"]
    facts = {key: asset.get(key) for key in ("online", "onlineBasis", "lastSeenAt", "lastProbeAt", "probeState", "stateEvidence")}
    evidence = asset.get("stateEvidence") or {}
    try:
        ip_address(asset.get("ip", ""))
        valid = evidence.get("online") == asset.get("online") and isinstance(evidence.get("signals"), list) and evidence.get("timeBasis") in ("DATABASE_LOCAL", "UTC", "OFFSET") and timestamp(evidence.get("evaluatedAt"))
    except ValueError:
        valid = False
    status, message = "unknown", "缺少有效状态证据或返回状态与证据冲突"
    if valid:
        signals = evidence["signals"]
        current = any(signal.get("validity") == "CURRENT" and signal.get("supportsOnline") is True and timestamp(signal.get("observedAt")) for signal in signals)
        if asset.get("online") == "online" and current:
            status, message = "normal", "SOC 在其状态时间窗口内报告在线"
        elif asset.get("online") == "offline" and not current and any(signal.get("validity") == "EXPIRED" and timestamp(signal.get("observedAt")) for signal in signals):
            status, message = "abnormal", "SOC 报告离线；不据此推断故障原因"
    return business().item(asset, {"status": status, "message": message, "facts": facts})

