"""基线证据判断；不以缺项或未检查推断通过。"""
from hep_lfx import business


async def read(value, operation, report=False):
    try:
        args = {"assetId": value["item"]["assetId"]}
        if report:
            args["includeChildren"] = False
        return {"data": (await business().request("ingest", operation, args)).get("data")}
    except Exception as error:
        return {"error": str(error)}


def assess(value, report_reply, ready_reply):
    asset = value["item"]
    report, ready = report_reply.get("data"), ready_reply.get("data")
    facts = {"report": report_reply if report_reply.get("error") else report, "readiness": ready_reply if ready_reply.get("error") else ready, "consistency": "两次读取不构成事务快照，未核实模板内容版本"}
    def result(status, message):
        return business().item(asset, {"status": status, "message": message, "facts": facts})
    def unknown(message):
        return result("unknown", message)
    if report_reply.get("error") or ready_reply.get("error"):
        return result("failed", "基线接口未完整返回，保留已取得的证据")
    integer = lambda n: type(n) is int and n >= 0
    if not isinstance(report, dict) or not isinstance(ready, dict) or str(ready.get("assetId")) != str(asset["assetId"]) or not isinstance(ready.get("items"), list) or type(ready.get("templateScopeMatched")) is not bool or not integer(ready.get("memberCount")) or not integer(ready.get("applicableCount")) or ready["applicableCount"] > ready["memberCount"] or len(ready["items"]) != ready["memberCount"]:
        return unknown("基线报告或就绪信息结构、对象与数量不一致")
    run = report.get("run")
    if run is not None and not isinstance(run, dict):
        return unknown("基线报告结构无效")
    if any(identity is not None and str(identity) != str(asset["assetId"]) for identity in (report.get("assetId"), (run or {}).get("assetId"))):
        return unknown("基线报告返回了不同资产")
    if not ready.get("templateId"):
        return unknown("当前未分配基线模板，不能判为通过或不适用")
    if not ready["templateScopeMatched"] or not ready["memberCount"] or any(item.get("conditionError") is not None for item in ready["items"]):
        return unknown("模板范围不匹配、没有成员项或存在配置错误")
    ids = [str(item.get("itemId")) for item in ready["items"]]
    if len(set(ids)) != len(ids) or any(item.get("itemId") is None or type(item.get("applicable")) is not bool or item["applicable"] != (item.get("applicabilityReason") == "MATCHED") for item in ready["items"]) or sum(item["applicable"] for item in ready["items"]) != ready["applicableCount"]:
        return unknown("逐项适用依据缺失、重复或矛盾")
    if not run:
        return unknown("SOC 未返回基线报告")
    if run.get("assetId") is None or str(run.get("templateId", report.get("templateId"))) != str(ready["templateId"]):
        return unknown("报告主体或当前模板身份无法核实")
    flag = str(run.get("passFlag")) if run.get("passFlag") is not None else ""
    reason = run.get("notCheckedReason")
    if flag in ("0", "1") and reason:
        return unknown("基线通过标志与未检查原因冲突")
    if not ready["applicableCount"]:
        if ready.get("assetType") and ready.get("coverageReason") == "NO_APPLICABLE_ITEM" and all(item.get("applicabilityReason") == "ASSET_SCOPE_NOT_MATCHED" for item in ready["items"]) and not flag and reason in ("NO_APPLICABLE_ITEM", "NO_APPLICABLE_ITEMS"):
            return result("not_applicable", "报告与当前逐项证据均明确无适用项")
        return unknown("没有有效适用项；停用、不支持及缺少配置不能当作不适用")
    if ready.get("coverageReason") != "APPLICABLE_ITEMS_PRESENT":
        return unknown("当前适用数量与覆盖原因冲突")
    if flag in ("0", "1"):
        return result("normal" if flag == "1" else "abnormal", "读取到的基线报告标记为" + ("达标" if flag == "1" else "不达标") + "；未核实模板内容版本及报告时效")
    return unknown("SOC 未给出可判定的基线结论")

